+const fs = require("fs");
+const assert = require("assert");
+const a = fs.readFileSync("lib/actions.ts", "utf8");
+const w = fs.readFileSync("app/api/webhook/route.ts", "utf8");
+assert(!a.includes("payment_method_types"), "payment_method_types present");
+assert(a.includes("2026-09-30.endive") && w.includes("2026-09-30.endive"), "not endive");
+const v = JSON.parse(fs.readFileSync("node_modules/stripe/package.json", "utf8")).version;
+assert(v.startsWith("23."), "stripe version " + v);
+console.log("ok");
